<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\Accessor\ThemeVersionChannelAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeVersionChannelAccessor trait.
 *
 * Covers null default, string/VO assignment via withChannel,
 * getChannel/channel accessors, and isChannelChanged with/without original.
 */
class ThemeVersionChannelAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withChannel creates a new instance with the Channel set
     * from a string value, and getChannel returns the primitive string.
     */
    public function testWithChannelFromString(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionChannelAccessorUnitTest();

        // Act
        $result = $holder->withChannel(ThemeVersionChannelOptions::MAIL);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(ThemeVersionChannelOptions::MAIL, $result->getChannel());
    }
    /**
     * Asserts that withchannel has access to the value object
     * from a string value, and getChannel returns the primitive string.
     */
    public function testWithChannelFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionChannelAccessorUnitTest();

        // Act
        $result = $holder->withChannel(ThemeVersionChannelOptions::MAIL);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(ThemeVersionChannelOptions::MAIL, $result->channel()->value());
    }
    public function testChangedChannel(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionChannelAccessorUnitTest()->withChannel(ThemeVersionChannelOptions::MAIL);
        $original = $holder->withChannel(ThemeVersionChannelOptions::MAIL);
        $same = $holder->withChannel(ThemeVersionChannelOptions::MAIL);
        $modified = $holder->withChannel(ThemeVersionChannelOptions::HTML);

        // Act
        $withSame = $original->isChannelChanged($same);
        $withDiferent = $original->isChannelChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithThemeVersionChannelAccessorUnitTest
{
    use ThemeVersionChannelAccessor;
}
